mapper.sql:
WHERE general_ledgers.is_approve = 1 AND general_ledgers.is_active = 1 AND general_ledger_details.chart_account_id IN ( SELECT id FROM chart_accounts WHERE chart_account_type_id = 2 )
AND ( general_ledger_details.type LIKE CONCAT('%', #{filter.searchText}, '%') OR general_ledgers.reference LIKE CONCAT('%', #{filter.searchText}, '%') OR sales_orders.so_code LIKE CONCAT('%', #{filter.searchText}, '%') OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%') )
AND general_ledgers.date >= #{filter.dateFrom}
AND general_ledgers.date <= #{filter.dateTo}
AND general_ledger_details.class_id = #{filter.classId}
AND general_ledger_details.customer_id = #{filter.organizationId}
AND general_ledger_details.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})
AND general_ledgers.is_adj = #{filter.adjustmentEntry}
AND general_ledgers.is_sys = #{filter.input}
AND general_ledgers.sales_order_id NOT IN ( SELECT gls.sales_order_id FROM general_ledgers gls INNER JOIN general_ledger_details glds ON gls.id = glds.general_ledger_id WHERE gls.sales_order_id IS NOT NULL AND (glds.type = 'Payment' OR glds.type = 'Credit Memo') )
AND general_ledgers.sales_order_id IN ( (SELECT gl.sales_order_id as so_id FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id AND gld.type = 'Invoice' AND round(gld.debit,2) > (SELECT round(SUM(glds.credit),2) FROM general_ledger_details glds INNER JOIN general_ledgers gls ON gls.id = glds.general_ledger_id WHERE gls.sales_order_id = gl.sales_order_id AND gls.sales_order_id IS NOT NULL AND (glds.type = 'Payment' OR glds.type = 'Credit Memo') ) GROUP BY gl.sales_order_id) )
AND (general_ledger_details.type = 'Credit Memo' OR general_ledger_details.type = 'Payment')
AND general_ledgers.sales_order_id IN ( SELECT gl.sales_order_id FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id AND gld.type = 'Invoice' WHERE gl.sales_order_id IS NOT NULL GROUP BY gl.sales_order_id HAVING ROUND(SUM(gld.debit), 2) = IFNULL(( SELECT ROUND(SUM(glds.credit), 2) FROM general_ledger_details glds INNER JOIN general_ledgers gls ON gls.id = glds.general_ledger_id WHERE gls.sales_order_id = gl.sales_order_id AND gls.sales_order_id IS NOT NULL AND (glds.type = 'Payment' OR glds.type = 'Credit Memo') ), 0) )

mapper.select:
SELECT general_ledgers.id AS id, CONCAT_WS(' ', customers.customer_code, customers.name) AS organizationName, (SELECT so_code FROM sales_orders WHERE id = general_ledgers.sales_order_id) AS invoiceCode, general_ledger_details.type AS type, general_ledgers.date AS `date`, general_ledgers.reference AS reference, CASE WHEN general_ledgers.sales_order_id IS NOT NULL THEN sales_orders.memo WHEN general_ledgers.receive_payment_id IS NOT NULL THEN ( SELECT note FROM receive_payments WHERE id = general_ledgers.receive_payment_id ) WHEN general_ledgers.ar_aging_id IS NOT NULL THEN ( SELECT note FROM ar_agings WHERE id = general_ledgers.ar_aging_id ) ELSE '' END AS memo, (SELECT CONCAT(account_codes, ' · ', account_description) FROM chart_accounts WHERE id = general_ledger_details.chart_account_id) AS account, IF(general_ledger_details.debit > 0, general_ledger_details.debit, general_ledger_details.credit * -1) AS amount, IF(general_ledger_details.debit > 0, general_ledger_details.debit, general_ledger_details.credit * -1) AS balance FROM general_ledgers INNER JOIN general_ledger_details ON general_ledgers.id = general_ledger_details.general_ledger_id LEFT JOIN customers ON general_ledger_details.customer_id = customers.id INNER JOIN sales_orders ON general_ledgers.sales_order_id = sales_orders.id
ORDER BY sales_orders.so_code ASC, general_ledgers.date ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
